import sys

def main():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    # Read N and D
    try:
        N = int(next(iterator))
        D = int(next(iterator))
    except StopIteration:
        return

    # Read the snakes' properties
    snakes = []
    for _ in range(N):
        T = int(next(iterator))
        L = int(next(iterator))
        snakes.append((T, L))

    # Iterate k from 1 to D
    for k in range(1, D + 1):
        max_weight = 0
        for T, L in snakes:
            # Calculate weight for current k
